// Design-only prototype. No persistence, model calls, identity verification or external actions.
const asset = '../public/assets/whyduck/';
const ducks = [
 {id:'butler',name:'管家鸭',role:'总管家 · 任务分派',desc:'不知道找谁？鸭来安排',color:'#fff1c6',tags:['理解诉求','邀请专业鸭','汇总办事单'],greeting:'先告诉鸭发生了什么。鸭会帮你选合适的伙伴，把下一步安排清楚。',output:'鸭鸭办事单'},
 {id:'analyst',name:'凭啥鸭',role:'消费问题分析官',desc:'先把事情捋清楚',color:'#fff5dc',tags:['倾听经历','区分事实与推测','诊断争议'],greeting:'先别急，鸭听着呢。把事情按你的方式说出来，我们一起分清已经知道的和还需要确认的。',output:'鸭鸭问题诊断卡'},
 {id:'detective',name:'据理力争鸭',role:'AI 证据侦探',desc:'查订单，核对商家说法',color:'#e5f1ff',tags:['识别截图','追溯原始材料','对比说法'],greeting:'把订单和客服截图放这里。鸭会标出来源，不清楚的地方请你核实。',output:'鸭鸭证据包'},
 {id:'refund',name:'退退退鸭！',role:'退换货军师',desc:'有理有据，谈退谈换',color:'#ffe8e2',tags:['比较处理方案','生成沟通草稿','核对适用条件'],greeting:'想退、想换，还是先维修？鸭帮你把各个方案的前提和风险说清楚，再写一份你能修改的话术。',output:'鸭鸭退换方案卡'},
 {id:'followup',name:'后手鸭',role:'售后跟进官',desc:'记承诺，盯进度，不烂尾',color:'#e8f4e8',tags:['记录商家承诺','创建待办','接续新进展'],greeting:'商家说什么时候回复？鸭帮你记下期限，到点回来继续处理。',output:'鸭鸭跟进计划'},
 {id:'escalation',name:'不服鸭',role:'协商升级顾问',desc:'协商不顺？再想办法',color:'#eee8fc',tags:['复盘协商','准备正式材料','核查官方渠道'],greeting:'我们先回看前面的沟通和证据，再决定怎么继续。有出处的事实，才是我们往前走的底气。',output:'鸭鸭下一步行动指南'}
];
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',chat:'M4 4h16v12H9l-5 4V4M8 8h8M8 12h5',cases:'M3 7h18v14H3zM8 7V3h8v4',evidence:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',tasks:'M8 3h8v4H8zM8 5H4v16h16V5h-4M7 12l2 2 3-4M14 13h3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',guide:'M4 4h7v16H4zM11 4h9v16h-9M7 8h1M14 8h3M14 12h3',duck:'M7 13c-4-3-3-8 1-8s4 4 4 4h5l4 3-4 2c2 7-12 10-14 3M7 9h.01',upload:'M12 16V3M7 8l5-5 5 5M4 15v6h16v-6',send:'m3 3 18 9-18 9 4-9-4-9M7 12h14',plus:'M12 4v16M4 12h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',arrow:'M4 12h16M14 6l6 6-6 6',bell:'M7 9a5 5 0 0 1 10 0v6l3 3H4l3-3V9M10 21h4',menu:'M4 6h16M4 12h16M4 18h16',back:'m14 5-7 7 7 7',download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',copy:'M8 8h13v13H8zM16 8V3H3v13h5',check:'m5 12 4 4 10-10',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l4 2',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 21v-3c0-7 16-7 16 0v3',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3',attachment:'m8 12 6-6c5-5 10 1 5 6l-9 9c-4 4-10-2-6-6L14 5M7 15l8-8',dots:'M5 12h.01M12 12h.01M19 12h.01',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.duck}"/></svg>`;
const avatar=id=>`<img class="avatar" src="${asset}avatars/${id}.webp" alt="${ducks.find(d=>d.id===id)?.name||'鸭鸭'}">`;
const stack=()=>`<div class="avatar-stack">${['butler','detective','refund','followup'].map(id=>`<img src="${asset}avatars/${id}.webp" alt="${ducks.find(d=>d.id===id).name}">`).join('')}</div>`;
const brand=()=>`<a href="#home" class="brand"><span class="brandmark"><img src="${asset}avatars/analyst.webp" alt="凭啥鸭品牌图形"></span><span>凭啥鸭</span><small>AI</small></a>`;
let route='home';
function navigation(){const items=[['home','首页','home'],['butler','管家鸭','duck'],['meeting','鸭鸭开会','chat'],['cases','我的案件','cases'],['evidence','消费凭证盒','evidence'],['tasks','跟进办事单','clock']];return `<aside class="sidebar">${brand()}<p class="brand-sub">你只管说事，鸭鸭组团办事！</p><div class="nav-label">鸭鸭事务所</div><nav>${items.map(([id,label,i])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav><div class="nav-label">快捷入口</div>${[['guide','鸭鸭使用指南','guide'],['brand','品牌与角色','duck'],['settings','设置与隐私','settings']].map(([id,label,i])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}">${icon(i)}<span>${label}</span></a>`).join('')}<a href="#account" class="sidebar-bottom"><span class="user-avatar">${icon('user')}</span><div><strong>设计体验用户</strong><br><small>本地 UI 示例</small></div>${icon('dots')}</a></aside>`}
function mobileNav(){return `<nav class="mobile-nav" aria-label="手机导航">${[['home','首页','home'],['meeting','鸭鸭开会','chat'],['cases','我的案件','cases'],['settings','我的','user']].map(([id,label,i])=>`<a class="${route===id?'active':''}" href="#${id}">${icon(i)}${label}</a>`).join('')}</nav>`}
const topbar=(title,subtitle='YOUR AFTER-SALES DUCK OFFICE')=>`<header class="topbar"><div class="mobile-only">${brand()}</div><div class="desktop-only"><div class="eyebrow">${subtitle}</div><h2>${title}</h2></div><div class="top-actions"><span class="pill">6 位专业鸭 · 按需协作</span><button class="round" data-action="reminders" aria-label="到期待办">${icon('bell')}</button><button class="round" data-action="menu" aria-label="全部页面">${icon('menu')}</button></div></header>`;
const heading=(title,description,action='')=>`<header class="topbar"><div><h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div>${action}</header>`;
const notice=text=>`<div class="notice">${text}</div>`;
function home(){return `<main class="main">${topbar('你好呀，今天有什么需要鸭鸭帮忙？','WELCOME TO THE DUCK OFFICE')}<section class="hero"><div class="hero-content"><span class="pill" style="background:#fffaf0">管家鸭今日值班</span><h1>这事儿，<br>凭啥呀？！</h1><p>退款难、客服绕、售后没下文？<br>把问题交给鸭鸭们，有理有据解决。</p><div class="hero-actions"><button class="primary" data-go="butler">找管家鸭帮忙 ${icon('arrow')}</button><button class="secondary" data-go="meeting">鸭鸭开会 ${icon('chat')}</button></div></div><img class="hero-art" src="${asset}characters/butler.webp" alt="戴黑帽、拿任务板的管家鸭欢迎你"><span class="hero-sticker">先吐槽，鸭来安排！</span></section><div class="composer-home">${icon('attachment')}<textarea id="home-input" aria-label="描述售后问题" placeholder="说说遇到的糟心事，或上传订单、客服截图……"></textarea><button class="round" data-action="upload" aria-label="添加截图">${icon('plus')}</button><button class="primary" data-go="meeting"><span>发送给管家鸭</span> ${icon('send')}</button></div><div class="examples"><button data-example="我买的耳机坏了，客服说三天退款，一星期还没处理。">退款一直没下文</button><button data-example="商家昨天说可以换货，今天又说不行。">商家前后说法不同</button><button data-example="我不知道应该准备哪些售后材料。">需要准备什么证据？</button></div><div class="section-head"><div><h2>今天找哪只鸭？</h2><p>每只鸭都有自己的绝活，不知道找谁就交给管家鸭</p></div><a href="#brand" class="link small">认识鸭鸭全家桶 →</a></div><section class="ducks-grid">${ducks.map(d=>`<article class="duck-card" style="background:${d.color}"><div class="duck-copy"><small>${d.role}</small><h3>${d.name}</h3><p>${d.desc}</p><button data-go="${d.id}">找它聊聊 ↗</button></div><img src="${asset}characters/${d.id}.webp" alt="${d.name}角色形象"></article>`).join('')}</section><p class="caption">凭啥鸭 · 售后鸭鸭局<br class="mobile-only">情绪有出口，证据有出处，售后有后手。</p></main>`}
const agentMessage=(id,content,time)=>`<article class="message">${avatar(id)}<div class="message-content"><div class="message-label">${ducks.find(d=>d.id===id).name}<time>${time}</time></div><div class="bubble">${content}</div></div></article>`;
const task=(title,id,done)=>`<label class="task"><input type="checkbox" ${done?'checked':''}><div><strong>${title}</strong><p>${ducks.find(d=>d.id===id).name} · ${done?'已完成':'待你确认'}</p></div></label>`;
function panel(){return `<section class="panel-section"><h3>${icon('tasks')} 鸭鸭办事单</h3><div class="case-summary"><small class="muted">当前案件 · 示例</small><h4>蓝牙耳机退款争议</h4><span class="pill">等待证据核实</span><p>¥299 · 用户描述，尚未确认</p><div class="progress"><span></span></div><p>已完成 2 / 4 项准备任务</p></div><div class="task-heading"><h3>下一步任务</h3><small>2 / 4</small></div>${task('创建售后案件','butler',true)}${task('整理用户主要诉求','analyst',true)}${task('补充商家承诺截图','detective',false)}${task('核对沟通方案并跟进','refund',false)}</section><section class="panel-section"><h3>${icon('evidence')} 消费凭证盒</h3><button class="evidence-mini" data-action="evidence"><span class="file-icon">${icon('evidence')}</span><span>E001 · 订单信息示例<br><span class="muted">用户描述 · 待确认</span></span></button><button class="evidence-mini" data-action="upload"><span class="file-icon">${icon('plus')}</span><span>补充客服聊天截图<br><span class="muted">还缺商家承诺的原始材料</span></span></button></section><a class="link small" href="#report">核对并导出办事报告 →</a><p class="legal-footnote">鸭鸭帮你整理和协商，不能替你作出法律裁决或保证退款结果。</p>`}
function composer(){return `<div class="chat-composer"><textarea id="chat-input" aria-label="聊天消息" placeholder="说说新情况，或 @ 一只鸭鸭继续处理……"></textarea><div id="mention-list"></div><div class="composer-actions"><div class="composer-tools"><button data-action="upload">${icon('attachment')} 上传截图</button><button data-action="mention">@ 选择鸭鸭</button><button data-action="members">${icon('plus')} 邀请成员</button></div><button class="primary" data-action="preview-send">发送 ${icon('send')}</button></div><div class="privacy-note">截图仅作材料。使用真实 AI 前需同意第三方模型处理；设计预览不会上传。</div></div>`}
function meeting(){return `<section class="chat-shell"><header class="chat-header"><div><h2>${icon('chat')} 鸭鸭开会 · 耳机退款争议</h2><p>4 位鸭鸭参与 · 按需分工 · 示例案件 WD-1024</p></div><div class="top-actions">${stack()}<button data-action="members">${icon('plus')} 邀请鸭鸭</button><button class="mobile-sheet-trigger" data-action="case-panel">办事单</button></div></header><div class="chat-body"><div class="conversation"><div class="messages"><div class="date-divider">10 月 8 日 14:26 · 设计示例对话</div><article class="message user"><div class="bubble">我花 299 元买了耳机，质量有问题，客服说三天内退款，现在一星期了还不处理，怎么办？</div></article><div class="system-message">管家鸭邀请：据理力争鸭、退退退鸭！、后手鸭</div>${agentMessage('butler',`先核对商家的承诺，再准备沟通方案。我把证据鸭、退款鸭和后手鸭请来了，一起捋清楚。`,'14:26')}${agentMessage('detective',`你提到「三天内退款」，目前只有你的描述，还不能作为已核实的商家承诺。请补充对应聊天截图。<div class="result-card"><h4>证据核对 · 还缺一点关键材料</h4><p>订单信息 <button class="citation" data-action="evidence">E001</button> · 示例材料，待确认</p><p>商家承诺截图 · 尚未提供</p><button data-action="upload">补充原始截图</button></div>`,'14:27')}${agentMessage('refund',`等承诺和订单核对后，我们可以再比较退款、换货或维修。先给你一份可修改的沟通草稿：<div class="result-card"><h4>理性坚定版 · 待核实后使用</h4><p>您好，关于这笔耳机订单，我已反馈使用问题。请确认目前的售后处理状态、方案和预计回复时间。若需补充材料，请一次说明。</p><div class="message-actions"><button data-go="drafts">修改草稿</button><button data-action="copy">${icon('copy')} 复制</button></div></div>`,'14:28')}${agentMessage('followup',`鸭先记一项待办：补充并核对承诺截图。处理期限也需要核对，再由你确认是否创建到期提醒。<div class="statusline">${icon('clock')} 待你确认 · 应用内跟进，不会自动发消息</div>`,'14:28')}</div>${composer()}</div><aside class="case-panel">${panel()}</aside></div></section>`}
function solo(id){const d=ducks.find(d=>d.id===id);const special={butler:'描述事情 → 确认关键事实 → 邀请专业鸭 → 生成办事单',analyst:'已知：用户描述耳机使用异常。待确认：购买日期、问题表现、商家实际承诺。',detective:'上传两次客服回复，鸭会逐条对比，并将差异链接到原始材料。',refund:'请先确认订单与已核实事实，再选择退款、换货或维修方向。',followup:'承诺日期与截止时间需要你确认。创建后可在跟进办事单中查看和完成。',escalation:'先复盘沟通记录。官方渠道与适用条件需要核查来源，未核实时不会给出确定结论。'};return `<main class="main">${heading(`${d.name} · 独立聊天`,'专业能力有分工，案件记忆可在你授权后接续。',`<button data-go="meeting">进入鸭鸭开会 ${icon('arrow')}</button>`)}<section class="role-hero" style="background:${d.color}"><img src="${asset}characters/${id}.webp" alt="${d.name}"><div><h1>${d.desc}</h1><p>${d.greeting}</p><div class="role-specialty">${d.tags.map(t=>`<span>${t}</span>`).join('')}</div></div></section><div class="grid-two"><section class="compact-chat chat-shell"><div class="messages">${agentMessage(id,d.greeting,'刚刚')}${agentMessage(id,`<div class="result-card"><h4>${d.output} · 输出示例</h4><p>${special[id]}</p><p class="muted">新对话开始前，请选择已有案件或创建新案件。</p><div class="horizontal-actions"><button data-action="choose-case">关联已有案件</button><button data-action="new-case">创建案件</button></div></div>`,'刚刚')}</div>${composer()}</section><aside class="card"><h3>这只鸭能帮你做什么？</h3>${d.tags.map((t,i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><h4>${t}</h4><p>结果关联当前案件，重要事实由你核对。</p></div></div>`).join('')}<div class="notice">${id==='detective'?'没有原始材料就不会编造识别结果。':id==='escalation'?'只协助整理材料，不冒充律师或政府机构。':id==='refund'?'文案可修改、复制和保存，不替你向商家发送。':'鸭鸭按需协作，新的事实会更新同一个案件。'}</div></aside></div></main>`}
function cases(){const rows=[['蓝牙耳机退款争议','等待证据核实','¥299','客服承诺需要原始截图确认，下一步补充材料。','黄'],['运动鞋换货沟通','跟进中','¥459','已整理两次回复，等待确认商家新的处理方案。','绿'],['咖啡机维修记录','已归档','¥899','示例案件已结束，材料与历史记录可以继续查看。','灰']];return `<main class="main">${heading('我的案件','事情一件一件理清楚，进度一步一步往前走。',`<button class="primary" data-action="new-case">${icon('plus')} 新建案件</button>`)}<div class="toolbar"><div class="search">${icon('search')}<input aria-label="搜索案件" placeholder="搜索案件名称、商家或编号"></div><div class="tabs"><button class="selected" data-filter="all">全部 3</button><button data-filter="active">处理中 2</button><button data-filter="archived">已归档 1</button></div></div><div class="grid-three" id="case-list">${rows.map(([title,status,amount,desc,color],i)=>`<article class="card case-card" data-case-state="${i===2?'archived':'active'}"><div class="case-top"><small class="muted">WD-${1024+i} · 设计示例</small><button class="link" data-action="case-options" aria-label="案件操作">${icon('dots')}</button></div><h3>${title}</h3><span class="pill ${color==='绿'?'green':color==='灰'?'gray':''}">${status}</span><p>${desc}</p><div class="case-meta"><span>${amount} · 用户描述</span><span>10 月 8 日更新</span></div><div class="case-footer">${stack()}<button data-go="meeting">继续处理 →</button></div></article>`).join('')}</div><div class="notice" style="margin-top:22px">这里展示的是设计示例。真实案件仅在登录账户内可见，删除前需要确认。</div></main>`}
const receipt=(type='order')=>`<div class="receipt"><strong>${type==='chat'?'客服回复 · 示例':'付款凭证 · 示例'}</strong>${type==='chat'?'<p>商家：请补充问题视频。</p><p>用户：已经上传。</p><p>商家：我们核对后回复。</p>':'<p>某数码店 · 蓝牙耳机</p><b>¥299.00</b><p>2026-09-30 · 用户提供</p><p>此处仅为设计示意</p>'}</div>`;
function evidence(){return `<main class="main">${heading('鸭鸭消费凭证盒','每一条关键事实，都能找到它的出处。',`<button class="primary" data-action="upload">${icon('upload')} 上传材料</button>`)}<section class="upload-zone"><div>${icon('upload')}</div><strong>把订单、付款凭证或客服截图放这里</strong><p>支持 PNG、JPG、WebP · 单张不超过 10 MB</p><button data-action="upload">选择文件</button><p>材料默认私有，识别结果需要你核对。</p></section><div class="toolbar"><div class="search">${icon('search')}<input aria-label="搜索材料" placeholder="搜索证据编号、商家或关联案件"></div><div class="tabs"><button class="selected" data-action="tab">全部材料</button><button data-action="tab">待确认 2</button><button data-action="tab">已确认 0</button></div></div><div class="grid-three">${['订单与付款凭证','商家售后回复','商品问题记录'].map((title,i)=>`<article class="card evidence-card"><div class="evidence-preview">${i===2?'<div class="small muted">商品问题记录 · 示例<br>原始照片或视频待补充</div>':receipt(i===1?'chat':'order')}</div><h3>E00${i+1} · ${title}</h3><p class="small muted">关联：蓝牙耳机退款争议 · 示例</p><span class="pill">${i===2?'待补充材料':'待人工核对'}</span><footer><span class="small muted">10 月 8 日</span><button ${i===0?'data-go="evidence-detail"':'data-action="evidence" data-evidence="E00'+(i+1)+'"'}>查看与核对 →</button></footer></article>`).join('')}</div><p class="legal-footnote">AI 提取与人工确认分别记录。原始材料中的文字不会成为系统指令。</p></main>`}
function evidenceDetail(){return `<main class="main">${heading('核对证据 · E001','识别只是起点，确认由你来完成。',`<button data-go="evidence">${icon('back')} 返回凭证盒</button>`)}<div class="evidence-layout"><section class="card"><div class="detail-head">${icon('evidence')}<h3>原始材料预览</h3><span class="pill gray">设计示意</span></div><div class="evidence-preview" style="height:350px;margin-top:20px">${receipt()}</div><p class="small muted">付款凭证示例.png · 此处没有真实用户材料</p><button data-action="preview-original">查看原图与上下文</button></section><section class="card"><div class="detail-head"><h3>AI 提取信息</h3><span class="pill">待你核对</span></div><div class="notice" style="margin-top:16px">金额、日期和商家名称均为设计示例。实际识别结果必须逐项确认。</div><dl class="facts"><dt>商家</dt><dd><input aria-label="商家名称" value="某数码店"></dd><dt>金额</dt><dd><input aria-label="金额" value="299.00"></dd><dt>日期</dt><dd><input type="date" aria-label="付款日期" value="2026-09-30"></dd><dt>商品</dt><dd><input aria-label="商品" value="蓝牙耳机"></dd><dt>退款状态</dt><dd><span class="pill gray">材料中未发现</span></dd><dt>原文引用</dt><dd>「¥299.00」<br><span class="muted">来源：E001 · 金额区域</span></dd><dt>关联案件</dt><dd><a class="link" href="#meeting">WD-1024 · 耳机退款争议</a></dd></dl><label class="small"><input type="checkbox" id="confirm-facts"> 我已对照原图核对以上信息</label><div class="modal-actions"><button data-action="save-facts">保存修改</button><button class="primary" data-action="confirm-facts">确认这些事实</button></div><p class="legal-footnote">修改事实后，相关方案与报告将标记为需要重新核对。</p></section></div></main>`}
function timeline(){return `<main class="main">${heading('证据时间线','蓝牙耳机退款争议 · WD-1024 · 设计示例',`<button data-go="evidence">${icon('plus')} 补充材料</button>`)}<div class="grid-two"><section class="card"><h3>把事情按时间捋清楚</h3><div class="timeline">${[['09 月 30 日','购买蓝牙耳机','金额 ¥299，用户描述，等待付款凭证核对。','E001'],['10 月 02 日 · 日期待确认','反馈商品问题','用户描述使用异常，需补充问题照片或视频。','E003'],['日期待确认','商家承诺三天内处理','目前没有对应聊天原图，不能确认为商家实际承诺。',null],['10 月 08 日','整理售后诉求','先补齐证据，再核对处理期限和沟通方案。',null]].map(([date,title,desc,ref])=>`<article class="timeline-item"><span class="timeline-date">${date}</span><h4>${title}</h4><p>${desc}</p>${ref?`<button class="citation" data-action="evidence" data-evidence="${ref}">${ref} · 查看来源</button>`:'<span class="pill">待补充材料</span>'}</article>`).join('')}</div></section><aside><section class="card"><h3>事实的三种状态</h3><p class="small"><span class="pill green">已确认</span> 你已对照原始材料核实。</p><p class="small"><span class="pill">待确认</span> 由 AI 提取，或来自用户描述。</p><p class="small"><span class="pill gray">缺少来源</span> 不能据此给出确定结论。</p><div class="notice">日期不清楚时保留「待确认」，不自动补出日期。</div></section><section class="card" style="margin-top:16px"><h3>商家说法对比</h3><p class="small muted">补充两次完整回复后，证据鸭会对照原文、时间和上下文标出差异。</p><button data-action="upload">上传两次回复</button></section></aside></div></main>`}
function tasks(){return `<main class="main">${heading('鸭鸭跟进办事单','售后别烂尾，咱还有后手鸭。',`<button class="primary" data-action="new-task">${icon('plus')} 添加待办</button>`)}<div class="stat-strip"><div class="stat"><strong>3</strong><span>待处理 · 示例</span></div><div class="stat"><strong>1</strong><span>今日需跟进</span></div><div class="stat"><strong>2</strong><span>已完成</span></div></div><div class="tabs" style="margin-bottom:16px"><button class="selected" data-action="tab">待处理</button><button data-action="tab">已完成</button><button data-action="tab">全部</button></div><section class="card">${[['核对商家承诺截图','耳机退款争议 · 据理力争鸭','今天 18:00','detective','red'],['确认沟通草稿，并自行发送','耳机退款争议 · 退退退鸭！','明天 10:00','refund',''],['回来记录客服新回复','运动鞋换货沟通 · 后手鸭','10 月 10 日','followup','gray']].map(([title,desc,date,id,color])=>`<label class="followup-row"><input type="checkbox"><div class="row-content"><h4>${title}</h4><p>${desc}</p></div><span class="pill ${color}">${icon('clock')} ${date}</span>${avatar(id)}</label>`).join('')}</section><div class="notice" style="margin-top:18px">首版提供应用内到期提示。站外推送尚未接通时，不展示为已发送通知。</div><div class="section-head"><h2>已完成的准备</h2></div><section class="card">${[['创建耳机售后案件','管家鸭 · 今天 14:26'],['整理用户主要诉求','凭啥鸭 · 今天 14:27']].map(([title,desc])=>`<label class="followup-row"><input type="checkbox" checked><div class="row-content"><h4>${title}</h4><p>${desc}</p></div><span class="pill green">已完成</span></label>`).join('')}</section></main>`}
function drafts(){return `<main class="main">${heading('沟通草稿','你来核对、修改和发送，鸭鸭只帮你把话说清楚。',`<button data-go="meeting">返回案件</button>`)}<div class="grid-two"><section class="card"><div class="tabs" style="margin-bottom:18px"><button class="selected" data-tone="firm">理性坚定版</button><button data-tone="gentle">温柔沟通版</button><button data-tone="formal">正式协商版</button></div><textarea id="draft" class="draft-text" aria-label="沟通草稿">您好，关于这笔耳机订单，我已反馈使用问题。请确认目前的售后处理状态、方案和预计回复时间。若需补充材料，请一次说明。谢谢。

订单编号：[请核对后填写]
问题描述：[补充具体表现]</textarea><div class="modal-actions"><button data-action="copy">${icon('copy')} 复制文案</button><button class="primary" data-action="save-draft">保存草稿</button></div></section><aside class="card"><h3>发送前核对一下</h3><label class="task"><input type="checkbox"><div><strong>订单编号与问题描述准确</strong><p>不确定的信息先补充</p></div></label><label class="task"><input type="checkbox"><div><strong>引用的商家承诺已有来源</strong><p>不把用户描述当作已核实事实</p></div></label><label class="task"><input type="checkbox"><div><strong>移除无关的个人信息</strong><p>不要复制地址、手机号等敏感材料</p></div></label><div class="notice">这份草稿没有保证退款结果，也不会自动向商家发送。</div></aside></div></main>`}
function report(){return `<main class="main">${heading('鸭鸭办事报告','先核对、再脱敏，最后导出。',`<button class="primary" data-action="export">${icon('download')} 核对与导出</button>`)}<div class="report-sheet"><div class="eyebrow">WHYDUCK · CASE REPORT</div><h1>蓝牙耳机退款争议</h1><div class="report-meta">WD-1024 · 更新于 2026-10-08 · 设计示例，非真实案件</div><h3>01 / 事件简介</h3><p>用户描述：花费 299 元购买耳机，反馈使用问题，称客服曾承诺三天内退款，目前仍未处理。购买金额与商家承诺均待原始材料核对。</p><h3>02 / 事实与证据</h3><ul><li>E001：付款凭证示意 · 金额待人工确认。</li><li>E002：商家回复示意 · 未包含三天退款承诺。</li><li>缺少材料：承诺原文、具体问题记录、完整时间信息。</li></ul><h3>03 / 已进行的处理</h3><p>创建案件，整理主要诉求，准备可修改的客服沟通草稿。没有发送消息、提交投诉或执行退款。</p><h3>04 / 下一步办事单</h3><ol><li>补充并确认订单与商家承诺截图。</li><li>核对商家处理条件与预计回复时间。</li><li>由用户修改、确认并自行发送沟通文案。</li><li>根据新回复继续跟进。</li></ol><h3>05 / 边界与说明</h3><p>本报告协助整理材料与沟通，不构成法律裁决，不保证退款结果。未核实的信息不能作为确定结论。</p><p class="caption">情绪有出口，证据有出处，售后有后手。</p></div></main>`}
function settings(){return `<main class="main">${heading('设置与隐私','账户、模型处理和平台授权，一项项说清楚。')}<div class="grid-two"><section class="card"><h3>${icon('user')} 账户与授权</h3><div class="settings-row"><div><strong>独立账户</strong><p>设计体验用户 · 正式开发后提供安全登录</p></div><button data-go="account">查看账户</button></div><div class="settings-row"><div><strong>支付宝账户关联</strong><p>需要官方授权与身份验证，不提供账单读取权限</p></div><span class="pill gray">待配置与联调</span></div><div class="settings-row"><div><strong>解除平台关联</strong><p>未关联时不可操作</p></div><button disabled>解除关联</button></div><h3 style="margin-top:25px">${icon('shield')} 数据与隐私</h3><div class="settings-row"><div><strong>允许第三方 AI 处理案件材料</strong><p>发送前告知模型服务，未同意时只保存材料</p></div><button class="switch" data-action="switch" aria-label="允许第三方 AI 处理" aria-pressed="false"></button></div><div class="settings-row"><div><strong>应用内到期提醒</strong><p>打开应用时查看待跟进事项</p></div><button class="switch on" data-action="switch" aria-label="应用内到期提醒" aria-pressed="true"></button></div><div class="settings-row"><div><strong>导出我的数据</strong><p>导出前可以核对与脱敏</p></div><button data-go="report">导出</button></div><div class="settings-row"><div><strong>删除案件及材料</strong><p>仅删除当前账户拥有的数据，操作前确认</p></div><button class="danger" data-action="delete">查看删除说明</button></div></section><aside><section class="card"><h3>AI 与接入状态</h3>${[['文本与视觉模型','待配置千问 API'],['多智能体协作','设计阶段'],['支付宝小程序','待开发与真机联调'],['MCP 服务','待开发与客户端验证'],['站外通知','尚未接通']].map(([name,state])=>`<div class="settings-row"><strong>${name}</strong><span class="pill gray">${state}</span></div>`).join('')}<p class="legal-footnote">状态必须来自实际配置与运行验证，不能以「写了代码」替代接入成功。</p></section><div class="notice" style="margin-top:16px">API Key 只保存在服务端。产品界面不要求用户粘贴开发者密钥。</div></aside></div></main>`}
function account(){return `<main class="main">${heading('欢迎来到鸭鸭局','登录后，昨天没办完的事情今天接着办。')}<section class="card auth-card">${brand()}<h2>把事情放心交给鸭鸭</h2><p>案件、材料和跟进记录保存在你的账户内。</p><div class="tabs"><button class="selected" data-auth="login">登录</button><button data-auth="register">创建账户</button></div><label class="field"><span>邮箱</span><input type="email" placeholder="you@example.com" autocomplete="email"></label><label class="field"><span>密码</span><input type="password" placeholder="输入密码" autocomplete="current-password"></label><div id="register-extra"></div><button class="primary" id="auth-submit" data-action="login-preview">登录</button><p class="auth-divider">支付宝登录需完成官方授权接入后开放</p><div class="notice">这是账户界面的设计预览，不会创建账户或收集密码。</div></section></main>`}
function guide(){return `<main class="main">${heading('鸭鸭使用指南','一句话讲清事情，下一步一起理清楚。')}<div class="grid-two"><section class="card">${[['把事情告诉管家鸭','说说商品、商家、时间、发生的问题和你想要的结果。'],['补充材料，核对事实','订单、付款凭证和聊天截图都可以。AI 提取需要你对照原图确认。'],['让专业鸭协作','管家按需邀请；也可以 @ 专业鸭，直接处理当前任务。'],['核对草稿，自己发送','沟通话术可以修改和保存。对外发消息与投诉由你确认执行。'],['回来继续跟进','新的商家回复接在同一个案件里，待办和历史记录不会丢。']].map(([title,desc],i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><h4>${title}</h4><p>${desc}</p></div></div>`).join('')}<button class="primary" data-go="butler">找管家鸭帮忙 →</button></section><aside class="card empty"><img src="${asset}illustrations/meeting.webp" alt="专业鸭鸭围桌协作"><h3>你只管说事，鸭鸭组团办事！</h3><p>有用、有趣、可信、可执行。<br>不编证据，不代发消息，不保证退款。</p></aside></div></main>`}
function brandPage(){return `<main class="main">${heading('凭啥鸭 · 视觉设计系统','保留参考图的角色身份，统一为同一个原创 IP 家族。')}<section class="brand-board">${ducks.map(d=>`<article class="brand-character" style="background:${d.color}"><img src="${asset}characters/${d.id}.webp" alt="${d.name}全身标准形象"><h3>${d.name}</h3><p>${d.role}</p><p>${d.desc}</p></article>`).join('')}</section><div class="section-head"><h2>暖黄为主，专业信息清楚可读</h2></div><div class="swatches">${[['#FFD65A','主品牌黄'],['#FFFDF6','背景米白'],['#25231F','深色文字'],['#E5F1FF','证据蓝'],['#FFE8E2','珊瑚红'],['#E8F4E8','鼠尾草绿'],['#EEE8FC','柔和紫']].map(([hex,label])=>`<div class="swatch" style="background:${hex};color:${hex==='#25231F'?'white':'#25231f'}">${label}<br>${hex}</div>`).join('')}</div><section class="card"><h3>角色与排版使用规范</h3><p class="small muted">导航使用真实字体品牌字；六鸭为透明底本地素材。常规图标采用统一线性图标。标题、按钮、证据状态不嵌入插画。辅助文字保持清晰对比，状态同时使用文字说明。</p><div class="horizontal-actions"><button data-action="states">查看状态组件</button><a href="#home"><button class="primary">查看首页效果 →</button></a></div></section></main>`}
function render(){route=location.hash.slice(1)||'home';const views={home,cases,evidence,'evidence-detail':evidenceDetail,timeline,tasks,drafts,report,settings,account,guide,brand:brandPage,meeting};const content=views[route]?views[route]():ducks.some(d=>d.id===route)?solo(route):home();document.getElementById('app').innerHTML=`<div class="layout">${navigation()}<div class="workspace">${content}</div></div>${mobileNav()}`;document.title=`${({home:'鸭鸭事务所',meeting:'鸭鸭开会',cases:'我的案件',evidence:'消费凭证盒',tasks:'跟进办事单',report:'办事报告'}[route]||ducks.find(d=>d.id===route)?.name||'UI 设计')} · 凭啥鸭`;window.scrollTo(0,0)}
const toast=text=>{const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3200)};
function modal(title,body,actions=''){const el=document.getElementById('modal');el.innerHTML=`<div class="modal-head"><h3>${title}</h3><button data-action="close" aria-label="关闭弹窗">×</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;el.showModal()}
function states(){modal('交互状态 · 设计组件',`<div class="state-grid"><section class="state-card"><h4>分析与加载</h4><p class="small"><span class="spinner"></span>据理力争鸭正在核对材料……</p><div class="skeleton"></div><div class="skeleton short"></div><button data-action="cancel-preview">取消分析</button></section><section class="state-card"><h4>调用失败</h4><div class="notice red">模型服务暂时不可用。材料已保留，请稍后重试。</div><button style="margin-top:10px" data-action="retry-preview">${icon('refresh')} 重试当前任务</button></section><section class="state-card"><h4>上传进度</h4><div class="statusline">订单截图.png · 60% · 示例</div><div class="progress"><span style="width:60%"></span></div><p class="small muted">格式或大小不符时，明确说明原因。</p></section><section class="state-card"><h4>确认与过期结果</h4><div class="notice">案件事实已修改。此方案需要重新核对。</div><p class="small muted">旧版本保留历史，不继续当作当前建议。</p></section><section class="state-card"><h4>还没有案件</h4><p class="small muted">先把事情告诉管家鸭，第一份办事单从这里开始。</p><button data-go="home">开始说事</button></section><section class="state-card"><h4>需要更多证据</h4><p class="small muted">截图没有日期或缺少上下文。鸭不会替你补出不存在的内容。</p><button data-action="upload">补充完整材料</button></section></div>`)}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-go]');if(!el)return;if(el.dataset.go){document.getElementById('modal').close();location.hash=el.dataset.go;return}if(el.dataset.example){document.getElementById('home-input').value=el.dataset.example;return}if(el.dataset.filter){document.querySelectorAll('[data-filter]').forEach(e=>e.classList.toggle('selected',e===el));document.querySelectorAll('[data-case-state]').forEach(c=>c.hidden=el.dataset.filter!=='all'&&c.dataset.caseState!==el.dataset.filter);return}if(el.dataset.tone){document.querySelectorAll('[data-tone]').forEach(e=>e.classList.toggle('selected',e===el));document.getElementById('draft').value={firm:'您好，关于这笔耳机订单，我已反馈使用问题。请确认目前的售后处理状态、方案和预计回复时间。若需补充材料，请一次说明。谢谢。',gentle:'您好，想跟您确认一下耳机售后的进度。方便告知目前处理到哪一步、还需要我补充什么材料吗？谢谢您。',formal:'关于该耳机订单的售后事项，请协助确认已收到的问题反馈、当前处理方案及预计回复时间。订单编号与相关材料将在核对后附上。'}[el.dataset.tone];return}if(el.dataset.auth){const register=el.dataset.auth==='register';el.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===el));document.getElementById('auth-submit').textContent=register?'创建账户':'登录';document.querySelector('[type="password"]').autocomplete=register?'new-password':'current-password';document.getElementById('register-extra').innerHTML=register?'<label class="field"><span>确认密码</span><input type="password" autocomplete="new-password" placeholder="再次输入密码"></label><label class="small"><input type="checkbox"> 我已阅读隐私说明和第三方 AI 处理说明</label>':'';return}const action=el.dataset.action;if(action==='close'){document.getElementById('modal').close();return}if(action==='states'||el.id==='state-button'){states();return}if(action==='menu'){modal('全部设计页面',`<div class="grid-two">${[['home','事务所首页'],['meeting','鸭鸭开会'],['cases','我的案件'],['evidence','消费凭证盒'],['evidence-detail','证据核对'],['timeline','证据时间线'],['tasks','跟进办事单'],['drafts','沟通草稿'],['report','办事报告'],['settings','设置与隐私'],['account','账户登录'],['guide','使用指南'],['brand','品牌与角色'],...ducks.map(d=>[d.id,d.name+'独立聊天'])].map(([id,name])=>`<button data-go="${id}">${name}</button>`).join('')}</div>`);return}if(action==='members'){modal('鸭鸭成员与任务分工',ducks.map(d=>`<div class="member-row"><img src="${asset}avatars/${d.id}.webp" alt="${d.name}"><div><h4>${d.name}</h4><p>${d.tags.join(' · ')}</p></div><button data-action="member-preview">${['butler','detective','refund','followup'].includes(d.id)?'已加入':'邀请'}</button></div>`).join(''));return}if(action==='mention'){const target=document.getElementById('mention-list');if(target)target.innerHTML=`<div class="member-panel">${ducks.map(d=>`<button data-mention="${d.name}"><img src="${asset}avatars/${d.id}.webp" alt="">${d.name}</button>`).join('')}</div>`;return}if(el.dataset.mention){const input=document.getElementById('chat-input');input.value=input.value.replace(/@[^\s]*$/,'')+'@'+el.dataset.mention+' ';document.getElementById('mention-list').innerHTML='';input.focus();return}if(action==='case-panel'){modal('当前案件 · 鸭鸭办事单',panel());return}if(action==='upload'){modal('添加消费凭证',`<div class="upload-zone">${icon('upload')}<strong>选择截图或拖拽文件到这里</strong><p>PNG / JPG / WebP · 单张不超过 10 MB</p><button data-action="file-preview">选择文件</button></div><label class="field"><span>关联案件</span><select><option>蓝牙耳机退款争议 · WD-1024</option><option>创建新案件</option></select></label><label class="small"><input type="checkbox"> 我同意将所选材料交给已配置的第三方模型识别</label><p class="legal-footnote">设计预览不会读取、保存或上传文件。真实功能开发后提供上传进度、取消和识别结果核对。</p>`,`<button data-action="close">取消</button><button class="primary" data-action="file-preview">确认并识别</button>`);return}if(action==='evidence'&&el.dataset.evidence==='E002'){modal('E002 · 商家售后回复',`<div class="evidence-preview" style="height:250px">${receipt('chat')}</div><dl class="facts"><dt>来源</dt><dd>客服回复示例 · 设计示意</dd><dt>原文</dt><dd>「请补充问题视频」「我们核对后回复」</dd><dt>核对状态</dt><dd>待人工核对，未发现三天退款承诺</dd></dl>`);return}if(action==='evidence'&&el.dataset.evidence==='E003'){modal('E003 · 商品问题记录',`<div class="notice">用户描述耳机使用异常。尚未提供问题照片或视频，没有原图可以展示。</div><dl class="facts"><dt>来源</dt><dd>用户原始描述 · 设计示例</dd><dt>核对状态</dt><dd>待补充材料，不能确认为商品质量结论</dd></dl>`,`<button data-action="upload" class="primary">补充问题材料</button>`);return}if(action==='evidence'||action==='preview-original'){modal('E001 · 原始材料与来源',`<div class="evidence-preview" style="height:270px">${receipt()}</div><dl class="facts"><dt>来源</dt><dd>付款凭证示例.png · 设计示意</dd><dt>引用</dt><dd>「¥299.00」· 金额区域</dd><dt>核对状态</dt><dd>待人工确认</dd></dl><div class="notice">原始材料、AI 提取和已确认事实分别展示。</div>`,`<button data-go="evidence-detail" class="primary">核对信息 →</button>`);return}if(action==='new-case'){modal('新建售后案件',`<label class="field"><span>案件名称</span><input placeholder="例如：蓝牙耳机退款争议"></label><label class="field"><span>发生了什么？</span><textarea placeholder="商品、商家、时间、问题，以及你想要的结果"></textarea><small>不知道怎么描述也没关系，管家鸭会继续询问。</small></label>`,`<button data-action="close">取消</button><button class="primary" data-go="meeting">查看创建后界面</button>`);return}if(action==='new-task'){modal('记录下一步跟进',`<label class="field"><span>待办事项</span><input placeholder="例如：核对商家预计回复时间"></label><label class="field"><span>跟进时间</span><input type="datetime-local" value="2026-10-09T10:00"></label><label class="field"><span>关联案件</span><select><option>蓝牙耳机退款争议</option><option>运动鞋换货沟通</option></select></label><div class="notice">时间来自商家原文或你的安排，由你确认。</div>`,`<button data-action="close">取消</button><button class="primary" data-action="save-task">保存待办</button>`);return}if(action==='export'){modal('核对与脱敏',`<label class="task"><input type="checkbox" checked><div><strong>隐藏订单号、地址、手机号和账户标识</strong><p>导出前查看最终内容</p></div></label><label class="task"><input type="checkbox" checked><div><strong>标明待确认事实和缺失材料</strong><p>不把推测当结论</p></div></label><div class="notice">当前为设计阶段，导出按钮仅展示交互，不生成真实案件文件。</div>`,`<button data-action="close">继续核对</button><button class="primary" data-action="export-preview">导出 Markdown</button>`);return}if(action==='delete'){modal('删除案件与材料',`<p>正式功能将展示当前案件名称、材料数量和删除范围，并要求你明确确认。</p><div class="notice red">删除后无法从应用内恢复。当前设计预览不会删除任何文件。</div>`,`<button data-action="close">保留案件</button><button class="danger" data-action="delete-preview">查看确认效果</button>`);return}if(action==='case-options'){modal('案件管理',`<label class="field"><span>案件名称</span><input value="蓝牙耳机退款争议"></label><div class="horizontal-actions"><button data-action="case-preview">保存名称</button><button data-action="case-preview">归档案件</button><button data-action="delete" class="danger">删除案件</button></div>`);return}if(action==='choose-case'){modal('接续已有案件',`<button data-go="meeting">WD-1024 · 蓝牙耳机退款争议 →</button>`);return}if(action==='switch'){const enabled=el.classList.toggle('on');el.setAttribute('aria-pressed',String(enabled));toast('仅改变预览状态，未保存授权');return}if(action==='tab'){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===el));toast('已切换设计状态，数据为示例');return}if(action==='confirm-facts'){toast(document.getElementById('confirm-facts').checked?'已展示确认效果；尚未写入数据库':'请先勾选「我已对照原图核对」');return}if(action==='reminders'){modal('今日需要你跟进',`<label class="task"><input type="checkbox"><div><strong>核对商家承诺截图</strong><p>今天 18:00 · 耳机退款争议 · 示例</p></div></label>`,`<button data-go="tasks" class="primary">查看办事单 →</button>`);return}const texts={'preview-send':'设计预览不调用 AI；此处展示提交后的协作界面','copy':'设计预览：正式开发将复制核对后的文案','save-draft':'草稿保存状态已展示；尚未写入数据库','save-task':'待办保存状态已展示；尚未写入数据库','save-facts':'修改状态已展示；相关结果需要重新核对','login-preview':'这是登录界面预览，不收集密码或创建账户','file-preview':'设计预览不会读取文件或发起模型识别','member-preview':'成员选择效果已展示；实际调度在开发阶段接入','retry-preview':'重试状态预览；尚未发起网络请求','cancel-preview':'取消状态预览；没有运行中的模型请求','export-preview':'导出交互预览；实际文件导出待开发','delete-preview':'确认交互预览；没有删除任何数据','case-preview':'案件操作预览；未修改真实数据'};if(texts[action])toast(texts[action]);});
document.addEventListener('input',event=>{if(event.target.id==='chat-input'&&event.target.value.endsWith('@'))document.querySelector('[data-action="mention"]').click();if(event.target.matches('.search input')&&route==='cases'){const query=event.target.value.trim();document.querySelectorAll('.case-card').forEach(c=>c.hidden=!c.textContent.includes(query))}});
document.getElementById('modal').addEventListener('click',event=>{if(event.target===event.currentTarget){const rect=event.currentTarget.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)event.currentTarget.close()}});
window.addEventListener('hashchange',render);render();
